from PIL import Image
import colorsys, collections

def hues_of(cs):
    h = collections.Counter()
    for c in cs:
        hh,l,s = colorsys.rgb_to_hls(*[v/255 for v in c])
        if s > 0.15 and l > 0.08:
            h[(int(hh*360)//30)*30] += 1
    total = sum(h.values())
    return {k: f"{v/total:.2f}" for k,v in sorted(h.items())}

im = Image.open('barcode.png').convert('RGB')
W,H = im.size; px = im.load()
cols=[]
for x in range(W):
    r=g=b=0
    for y in range(H):
        p=px[x,y]; r+=p[0]; g+=p[1]; b+=p[2]
    cols.append((r/H,g/H,b/H))
print("BARCODE hues:", hues_of(cols))

for vid,tw,name in [("UprcpdwuwCg",215,"Heathens"),("rYEDA3JcQqw",160,"RollingDeep"),("QFs3PIZb3js",160,"Propuesta")]:
    cs=[]
    p=0
    import os
    while os.path.exists(f"sb/{vid}_L2_M{p}.jpg"):
        img = Image.open(f"sb/{vid}_L2_M{p}.jpg").convert('RGB')
        iw,ih=img.size
        for ridx in range(ih//90):
            for cidx in range(iw//tw):
                t = img.crop((cidx*tw, ridx*90, (cidx+1)*tw, (ridx+1)*90)).resize((8,8))
                tp=t.load()
                rr=gg=bb=0
                for xx in range(8):
                    for yy in range(8):
                        q=tp[xx,yy]; rr+=q[0]; gg+=q[1]; bb+=q[2]
                cs.append((rr/64,gg/64,bb/64))
        p+=1
    print(f"{name} hues:", hues_of(cs))
EOF

