from PIL import Image
import colorsys, collections, os

def hue_hist(cs):
    h=collections.Counter()
    for c in cs:
        hh,l,s = colorsys.rgb_to_hls(*[max(0,min(255,v))/255 for v in c])
        if s>0.15 and l>0.08: h[(int(hh*360)//30)*30]+=1
    t=sum(h.values()) or 1
    return {k: round(h.get(k,0)/t,2) for k in range(0,360,30) if h.get(k,0)>0}

def thumbs(vid, tw):
    cs=[]; p=0
    while os.path.exists(f"sb/{vid}_L2_M{p}.jpg"):
        img=Image.open(f"sb/{vid}_L2_M{p}.jpg").convert('RGB')
        iw,ih=img.size
        for ridx in range(ih//90):
            for cidx in range(iw//tw):
                t=img.crop((cidx*tw,ridx*90,(cidx+1)*tw,(ridx+1)*90)).resize((8,8))
                tp=t.load(); rr=gg=bb=0
                for xx in range(8):
                    for yy in range(8):
                        q=tp[xx,yy]; rr+=q[0]; gg+=q[1]; bb+=q[2]
                cs.append((rr/64,gg/64,bb/64))
        p+=1
    return cs

print("BARCODE  hues:", hue_hist([tuple(Image.open('barcode.png').convert('RGB').getpixel((x,100))) for x in range(1000)]))
print("Heathens hues:", hue_hist(thumbs("UprcpdwuwCg",215)))
print("Believer hues:", hue_hist(thumbs("7wtfhZwyrcc",160)))
EOF

